const fs = require('node:fs');
const path = require('node:path');

const leafletDir = path.dirname(require.resolve('leaflet/dist/leaflet.js'));
const script = fs
  .readFileSync(path.join(leafletDir, 'leaflet.js'), 'utf8')
  .replace(/\/\/# sourceMappingURL=.*$/m, '');
let css = fs.readFileSync(path.join(leafletDir, 'leaflet.css'), 'utf8');

function pngData(name) {
  return `data:image/png;base64,${fs.readFileSync(path.join(leafletDir, 'images', name)).toString('base64')}`;
}

for (const name of ['layers.png', 'layers-2x.png', 'marker-icon.png']) {
  css = css.replaceAll(`images/${name}`, pngData(name));
}

const content = [
  '// Generated by scripts/generate-map-assets.cjs from leaflet@1.9.4 (BSD-2-Clause).',
  `export const LEAFLET_JS = ${JSON.stringify(script.replaceAll('</script', '<\\/script'))};`,
  `export const LEAFLET_CSS = ${JSON.stringify(css)};`,
  `export const MARKER_ICON = ${JSON.stringify(pngData('marker-icon.png'))};`,
  `export const MARKER_ICON_2X = ${JSON.stringify(pngData('marker-icon-2x.png'))};`,
  `export const MARKER_SHADOW = ${JSON.stringify(pngData('marker-shadow.png'))};`,
  '',
].join('\n');

const output = path.join(__dirname, '..', 'src', 'assets', 'leafletInline.ts');
fs.mkdirSync(path.dirname(output), { recursive: true });
fs.writeFileSync(output, content);
